import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { extname, join } from "node:path";
import { chromium } from "playwright";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const mime = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".png": "image/png",
  ".svg": "image/svg+xml",
};

const server = createServer(async (req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({
      traces: [{ id: 1, label: "Demo", n_points: 12, epsilon: 0.9, delta: 500 }],
    }));
    return;
  }
  if (url.pathname.startsWith("/api/trace")) {
    return;
  }
  const rel = url.pathname === "/" ? "/index.html" : url.pathname;
  try {
    const body = await readFile(join(root, rel));
    res.writeHead(200, { "content-type": mime[extname(rel)] || "application/octet-stream" });
    res.end(body);
  } catch {
    res.writeHead(404);
    res.end("not found");
  }
});

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const port = server.address().port;
const origin = `http://127.0.0.1:${port}`;

const browser = await chromium.launch();

async function measureHeader(page) {
  return page.evaluate(() => {
    const btn = document.querySelector("#loadBtn");
    const status = document.querySelector("#uploadStatus");
    const header = document.querySelector("header");
    const br = btn.getBoundingClientRect();
    const sr = status.getBoundingClientRect();
    return {
      btnWidth: Math.round(br.width * 10) / 10,
      btnLeft: Math.round(br.left * 10) / 10,
      statusLeft: Math.round(sr.left * 10) / 10,
      headerHeight: Math.round(header.getBoundingClientRect().height * 10) / 10,
      busy: btn.getAttribute("aria-busy"),
      labelVisible: getComputedStyle(btn.querySelector(".load-btn-label")).visibility,
    };
  });
}

async function captureLive(width, height, outPath, { clickLoad = true } = {}) {
  const page = await browser.newPage();
  await page.setViewportSize({ width, height });
  await page.goto(origin + "/", { waitUntil: "domcontentloaded" });
  await page.waitForSelector("#traceSelect option[value='1']");
  await page.selectOption("#traceSelect", "1");
  const idle = await measureHeader(page);
  if (clickLoad) {
    await page.click("#loadBtn");
    await page.waitForFunction(() => document.body.classList.contains("trace-loading"));
  }
  const busy = clickLoad ? await measureHeader(page) : idle;
  await page.screenshot({ path: outPath, fullPage: false });
  await page.close();
  return { idle, busy };
}

const fixture = await browser.newPage();
await fixture.setViewportSize({ width: 1280, height: 800 });
await fixture.goto(origin + "/usability/desktop-load-btn-width.html", { waitUntil: "domcontentloaded" });
await fixture.screenshot({
  path: join(root, "usability/desktop-load-btn-width.png"),
  fullPage: true,
});
await fixture.close();

const live1280 = await captureLive(1280, 800, join(root, "usability/desktop-load-btn-width-live.png"));
const live900 = await captureLive(900, 800, join(root, "usability/desktop-load-btn-width-900-live.png"));
const live390 = await captureLive(390, 844, join(root, "usability/mobile-load-btn-width-regression-live.png"));

console.log(JSON.stringify({ live1280, live900, live390 }, null, 2));

await browser.close();
server.close();

import { chromium } from "playwright-core";
import { pathToFileURL } from "node:url";
import http from "node:http";
import fs from "node:fs";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const usability = path.join(root, "usability");
const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";

const freezeSpinners = `
  const style = document.createElement("style");
  style.textContent = ".button-spinner, .params-spinner { animation: none !important; transform: rotate(40deg); }";
  document.head.appendChild(style);
`;

function mime(filePath) {
  if (filePath.endsWith(".js")) return "text/javascript";
  if (filePath.endsWith(".css")) return "text/css";
  if (filePath.endsWith(".html")) return "text/html";
  if (filePath.endsWith(".svg")) return "image/svg+xml";
  return "application/octet-stream";
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ traces: [{ id: 1, n_points: 12, label: "Demo" }] }));
    return;
  }
  if (url.pathname.startsWith("/api/trace")) {
    return;
  }
  const filePath = url.pathname === "/"
    ? path.join(root, "index.html")
    : path.join(root, url.pathname.replace(/^\//, ""));
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end("not found");
      return;
    }
    res.writeHead(200, { "Content-Type": mime(filePath) });
    res.end(data);
  });
});

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const origin = `http://127.0.0.1:${server.address().port}`;
const browser = await chromium.launch({ executablePath: chrome, headless: true });

function measure(page) {
  return page.evaluate(() => {
    const btn = document.getElementById("loadBtn");
    const status = document.getElementById("uploadStatus");
    const header = document.querySelector("header");
    const label = btn.querySelector(".load-btn-label");
    const spinner = btn.querySelector(".button-spinner");
    const br = btn.getBoundingClientRect();
    const sr = status.getBoundingClientRect();
    return {
      innerWidth: window.innerWidth,
      btnWidth: Math.round(br.width * 10) / 10,
      btnLeft: Math.round(br.left * 10) / 10,
      statusLeft: Math.round(sr.left * 10) / 10,
      headerHeight: Math.round(header.getBoundingClientRect().height * 10) / 10,
      busy: btn.getAttribute("aria-busy"),
      labelVisibility: label ? getComputedStyle(label).visibility : null,
      spinnerOpacity: spinner ? Number(getComputedStyle(spinner).opacity) : null,
      fileControlsDisplay: getComputedStyle(document.querySelector(".file-controls")).display,
    };
  });
}

async function captureLive(width, height, outPath) {
  const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 });
  await page.goto(origin, { waitUntil: "domcontentloaded" });
  await page.waitForFunction(() => document.querySelectorAll("#traceSelect option").length > 1);
  await page.evaluate((script) => { eval(script); }, freezeSpinners);
  await page.selectOption("#traceSelect", "1");
  const idle = await measure(page);
  await page.click("#loadBtn");
  await page.waitForSelector("#traceLoadingHud.visible");
  await page.waitForTimeout(200);
  const busy = await measure(page);
  await page.screenshot({ path: outPath });
  await page.close();
  return { idle, busy };
}

try {
  const fixturePage = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
  await fixturePage.goto(pathToFileURL(path.join(usability, "desktop-load-btn-width.html")).href, { waitUntil: "domcontentloaded" });
  await fixturePage.evaluate((script) => { eval(script); }, freezeSpinners);
  await fixturePage.screenshot({ path: path.join(usability, "desktop-load-btn-width.png"), fullPage: true });
  await fixturePage.close();

  const live1280 = await captureLive(1280, 800, path.join(usability, "desktop-load-btn-width-live.png"));
  const live900 = await captureLive(900, 800, path.join(usability, "desktop-load-btn-width-900-live.png"));
  const live390 = await captureLive(390, 844, path.join(usability, "mobile-load-btn-width-regression-live.png"));
  console.log(JSON.stringify({ live1280, live900, live390 }, null, 2));
} finally {
  await browser.close();
  server.close();
}

